import {SCENARIOS,PLAYERS,clock} from './engine.js';
import {sequenceBrief,productionPacket,datasetRows} from './studio-lab-model.js';
const $=id=>document.getElementById(id),el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
let current={scenario:'wide',time:18,corrected:false,focus:7,section:'watch'},language='en',cueLanguage='en',cueMode='beginner',stage='ingest';
const scenario=()=>SCENARIOS.find(s=>s.id===current.scenario)||SCENARIOS[0];
const options=()=>({language:cueLanguage,mode:cueMode,corrected:current.corrected,focus:current.focus});
function save(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function dataset(){save(`btr-${scenario().id}-${current.time.toFixed(1)}s.jsonl`,datasetRows(scenario(),current.time,options()).map(x=>JSON.stringify(x)).join('\n')+'\n','application/x-ndjson');}
function cue(){save(`btr-cue-${scenario().id}-${cueLanguage}.json`,productionPacket(scenario(),current.time,options()));}
for(const id of ['download-sequence','download-dataset','proof-dataset'])$(id).addEventListener('click',dataset);
for(const id of ['download-cue','proof-cue'])$(id).addEventListener('click',cue);
for(const b of document.querySelectorAll('[data-jump]'))b.addEventListener('click',()=>{$(b.dataset.jump+'-nav').click();window.scrollTo({top:0,behavior:'smooth'});});
$('brief-language').addEventListener('change',()=>{language=$('brief-language').value;renderCenter();});
$('cue-mode-select').addEventListener('change',()=>{cueMode=$('cue-mode-select').value;renderProduction();});
$('cue-language').addEventListener('change',()=>{cueLanguage=$('cue-language').value;renderProduction();});
function renderCenter(){
 const s=scenario(),b=sequenceBrief(s,current.time,{language,corrected:current.corrected,focus:current.focus}),m=b.state.metrics;
 $('sequence-title').textContent=s.title;$('sequence-score').textContent=`${b.score.harbor} : ${b.score.north}`;
 $('sequence-metrics').replaceChildren();
 for(const [value,label,detail]of [[b.state.seen.length,'EVENTS RECEIVED','Completed by '+b.clock],[m.completion===null?'—':m.completion+'%','HARBOR PASS COMPLETION',`${m.completed} completed / ${m.passes} attempted`],[m.speed===null?'—':m.speed.toFixed(1),'LATEST HARBOR PASS SPEED','km/h · distance ÷ time'],[b.shotSpeed===null?'—':b.shotSpeed.toFixed(1),'LATEST SHOT SPEED','km/h · synthetic coordinates']]){const item=el('article');item.append(el('span','',label),el('strong','',String(value)),el('small','',detail));$('sequence-metrics').append(item);}
 $('brief-cards').replaceChildren();for(const [i,c]of b.cards.entries()){const item=el('article');item.append(el('span','card-index','0'+(i+1)),el('h3','',c.label),el('p','',c.text));if(c.equation)item.append(el('div','brief-equation',c.equation));if(c.note)item.append(el('small','',c.note));$('brief-cards').append(item);}
 const signature=b.state.seen.map(e=>e.id).join('|')+current.scenario;
 if($('sequence-events').dataset.signature!==signature){$('sequence-events').dataset.signature=signature;$('sequence-events').replaceChildren();if(!b.state.seen.length)$('sequence-events').append(el('p','event-empty','The wire is waiting for the first completed event. Press play to start the sequence.'));
 for(const e of b.state.seen){const button=el('button','event-chip'),person=PLAYERS.find(p=>p.id===e.from),receiver=PLAYERS.find(p=>p.id===(e.interceptor||e.to));button.append(el('span','',clock(s,e.end)),el('b','',e.type==='tackle'?'RECOVERY':e.type.toUpperCase()),el('strong','',person.name),el('small','',`${receiver?'→ '+receiver.name+' · ':''}${e.outcome}`));button.setAttribute('aria-label',`Replay ${e.id} at ${clock(s,e.end)}`);button.addEventListener('click',()=>document.dispatchEvent(new CustomEvent('btr-seek-scenario',{detail:{scenario:s.id,time:e.end}})));$('sequence-events').append(button);}}
}
const stageCopy={
 ingest:{title:'A shared clock. A traceable event.',body:'Completed passes, shots and recoveries enter the tactical sequence at their recorded time. The Azure Match lab streams a separate ninety-minute synthetic fixture. Every export declares its source.',proof:'Current sequence events',value:b=>String(b.state.seen.length),action:'Open Match Centre ↗',target:'centre'},
 interpret:{title:'Calculate first. Interpret second.',body:'Distances use pitch coordinates. Average ball speed is distance divided by elapsed time. Completion uses completed passes over attempts. These calculated facts stay separate from tactical interpretation.',proof:'Harbor passes completed / attempted',value:b=>`${b.state.metrics.completed} / ${b.state.metrics.passes}`,action:'Inspect the math ↗',target:'centre'},
 explain:{title:'Every story has something to point to.',body:'Azure AI powers the watch-party editorial handoff and full-match checkpoint narratives. The instant sequence preview below uses authored rules and translations. Truth Lab demonstrates what happens when supporting data changes.',proof:'Evidence references in this cue',value:b=>String(b.evidenceIds.length),action:'Challenge the evidence ↗',target:'truth'},
 render:{title:'An insight with a place and a time.',body:'The output contract includes a lower-third placement, clock, expiry, revision and evidence references. Preview it below and download the JSON. A broadcast rendering partner is not connected.',proof:'Current sequence cutoff',value:b=>b.cutoff.toFixed(1)+'s',action:'See the video overlays ↗',target:'watch'},
 personalize:{title:'Different questions. The same facts.',body:'A newcomer gets the meaning of a pass. A curious viewer gets the denominator and units. An analyst gets tactical context. Three languages are available here; Watch and Match lab also include fan and player perspectives.',proof:'Languages / sequence perspectives',value:()=> '3 / 3',action:'Compare the perspectives ↗',target:'centre'}
};
function renderStage(){const b=sequenceBrief(scenario(),current.time,options()),copy=stageCopy[stage],text=el('div','pipeline-copy'),stat=el('div','pipeline-stat');text.append(el('span','eyebrow','THE '+stage.toUpperCase()+' STAGE'),el('h3','',copy.title),el('p','',copy.body));const button=el('button','outline-button',copy.action);button.addEventListener('click',()=>$(copy.target+'-nav').click());text.append(button);stat.append(el('strong','',copy.value(b)),el('span','',copy.proof));$('pipeline-detail').replaceChildren(text,stat);$('pipeline-detail').setAttribute('aria-labelledby','step-'+stage);for(const button of document.querySelectorAll('[data-stage]')){const active=button.dataset.stage===stage;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;}}
for(const b of document.querySelectorAll('[data-stage]')){b.addEventListener('click',()=>{stage=b.dataset.stage;renderStage();});b.addEventListener('keydown',e=>{const names=Object.keys(stageCopy);if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const i=names.indexOf(stage),next=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowRight'?1:4))%5;stage=names[next];renderStage();$('step-'+stage).focus();});}
function renderProduction(){const p=productionPacket(scenario(),current.time,options());$('cue-mode').textContent=p.overlay.headline;$('cue-copy').textContent=p.overlay.body;$('cue-equation').textContent=p.overlay.equation||'';$('cue-equation').hidden=!p.overlay.equation;$('cue-evidence').textContent=`${p.evidence_ids.length} evidence references · revision ${p.revision} · ${p.sequence_ms/1000}s cutoff`;$('cue-json').textContent=JSON.stringify(p,null,2);renderStage();}
document.addEventListener('btr-analysis-state',e=>{current=e.detail;if(current.section==='centre')renderCenter();if(current.section==='inside')renderProduction();});
document.dispatchEvent(new CustomEvent('btr-analysis-request'));renderCenter();renderProduction();
document.addEventListener('btr-section',e=>{if(['watch','centre','presenters','truth','inside','lab'].includes(e.detail))history.replaceState(null,'','#'+e.detail);});
const initialSection=location.hash.slice(1);if(['centre','presenters','truth','inside','lab'].includes(initialSection))$(initialSection+'-nav').click();
$('download-brief').addEventListener('click',()=>save('before-the-roar-project-brief.txt',`BEFORE THE ROAR — HACKATHON PROJECT BRIEF\n\nProblem: The scoreline does not explain a match, and a single commentary style does not serve every viewer.\n\nSolution: A broadcast-style football experience combining a generated film, a public three-role Azure AI discussion, synthetic match simulation, evidence checks, and personalized explanations.\n\nFive stages\n1. Ingest: Seeded synthetic full-match events on Azure, plus independent authored tactical scenarios.\n2. Interpret: Calculated passes, shots, distance, speed and event-based match context.\n3. Explain: Azure AI checkpoint stories and recaps; Scout, Check and Host discuss reviewed video observations.\n4. Render: Timed on-screen graphics and exportable JSON cues with evidence IDs and expiry.\n5. Personalize: Fan, beginner, math, analyst and player views; English, Spanish and Portuguese.\n\nDemo route\nWatch: Play the film, read the three public AI contributions, replay a citation.\nMatch Centre: Play a synthetic sequence, select a player, compare three explanation modes.\nTruth Lab: Apply the defender tracking correction and inspect the withdrawn claim.\nInside BTR: Change language and audience; export the cue and JSONL dataset.\nMatch lab: Run the Azure synthetic fixture through full time and export its AI-backed recap.\n\nAzure implementation: Container Apps backend, Azure OpenAI structured streaming, managed identity, private Blob cache and daily request reservations. Existing resources are reused.\n\nData boundaries: The generated film has five manually reviewed observations, not automatic pixel analysis. Tactical scenarios and the full-match stream are separate fixtures. Scenario explanations are deterministic; AI is used in Watch and Match lab. Synthetic portraits represent fictional personas. No real Premier League match data or league affiliation.\n\nNot implemented: Automatic video eventing, inferred player identification, calibrated pass difficulty, broadcast-partner integration, Fabric integration, and production-scale reliability validation.\n\nDifferentiator: Visible public editorial handoffs, replayable evidence, correction-aware explanations, and accessible football and math learning.\n`, 'text/plain'));
